<script lang="ts">
	import { targetOwner } from "$platform/target-owner";
	import { setUploadOwner } from "$platform/upload-batch";
	import { beforeNavigate, goto } from "$app/navigation";
	import { Constants, Mutex, Utils } from "$lib";
	import API from "$lib/API";
	import { currentUpload, prepareResume, snapshot, signature, saveResume, acknowledge, immutableCommit, resumeNotice, cancelResume, resumeError } from "$platform/upload-resume";
	import Guidelines from "$lib/components/Guidelines.svelte";
	import ConfirmDialog from "$lib/components/ConfirmDialog.svelte";
	import ReportMangaCard from "$lib/components/ReportMangaCard.svelte";
	import { Button } from "$lib/components/ui/button/index.js";
	import Checkbox from "$lib/components/ui/checkbox/checkbox.svelte";
	import * as Dialog from "$lib/components/ui/dialog";
	import Label from "$lib/components/ui/label/label.svelte";
	import { Separator } from "$lib/components/ui/separator";
	import { Spinner } from "$lib/components/ui/spinner";
	import UploadChapterGroups from "$lib/components/upload/UploadChapterGroups.svelte";
	import UploadChapterMetadata from "$lib/components/upload/UploadChapterMetadata.svelte";
	import UploadChapterPages from "$lib/components/upload/UploadChapterPages.svelte";
	import { setMutex, setUploadSession } from "$lib/Context.js";
	import { StatusCodes } from "http-status-codes";
	import { toast } from "svelte-sonner";
	import { onMount } from "svelte";

	const {
		manga,
		user
	}: {
		manga: Manga;
		user: User;
	} = $props();
	const mutex = new Mutex();
	const owner = targetOwner(() => manga.id, user.id);
	setUploadOwner(owner);

	let uploadSession = $state<UploadSession>();
	let draft = $state<ChapterDraft>({});
	let resumeReady = $state(false);
	let groups = $state<ScanlationGroup[]>([]);

	const isVolumeValid = $derived(draft?.volume ? Utils.isValidVolumeChapter(draft.volume) : true);
	const isChapterValid = $derived(draft?.chapter ? Utils.isValidVolumeChapter(draft.chapter) : true);

	let isOneshot = $state(false);
	let isTemsAccepted = $state(false);
	let isValid = $derived(
		resumeReady && uploadSession?.can_retry_commit !== false && !uploadSession?.is_committed && isTemsAccepted &&
			draft?.language?.length &&
			(isOneshot || (isVolumeValid && isChapterValid)) &&
			uploadSession?.relationships.files?.length &&
			uploadSession?.relationships?.files?.every(e => e.id.length === 10 && !e.file && !e.error)
	);

	setMutex(mutex);
	setUploadSession(() => uploadSession);

	let submitter = $state<string>();
	const createUploadSession = async (ev?: SubmitEvent) => {
		ev?.preventDefault();
		ev?.stopPropagation();
		ev?.stopImmediatePropagation();

		return mutex.exec(async () => {
			if (!resumeReady || uploadSession) {
				return;
			}

			const { pathname } = window.location;
			submitter = (<HTMLButtonElement>ev?.submitter)?.value;

			try {
				const res = await owner.request<UploadSession>("/upload/begin", "POST", { manga: owner.id, groups: groups.map(e => e.id) });
				if (window.location.pathname !== pathname) {
					return;
				}

				if (res?.status === StatusCodes.CREATED && res.body) {
					(res.body.relationships ??= {}).files = [];
					uploadSession = res.body;
					lastSavedUpload = signature(snapshot(res.body.draft ?? {}, res.body.relationships.files ?? []));
				} else if (res?.status === StatusCodes.FORBIDDEN) {
					throw Constants.Error.Forbidden;
				} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
					throw Constants.Error.TooManyRequests;
				} else throw Constants.Error.Unknown;
			} catch (e) {
				await reconcileUploadFailure();
				if (e instanceof Constants.Error.Error) toast.error(e.title, { description: e.body });
				else toast.error(Constants.Error.Unknown.title, { description: Constants.Error.Unknown.body });
			} finally {
				submitter = undefined;
			}
		});
	};

	let message = $state<{ title: string; description: string }>();
	let isShowMessage = $state(false);
	let isBeginAnotherUploadSession = $state(false);
	let chapter = $state<Chapter>();

	const commitUploadSession = async (ev: SubmitEvent) => {
		ev.preventDefault();
		ev.stopPropagation();
		ev.stopImmediatePropagation();

		return mutex.exec(async () => {
			const target = <HTMLButtonElement>ev.submitter;
			if (!uploadSession?.relationships?.files?.length || !isValid || !target) {
				return;
			}

			const { pathname } = window.location;
			submitter = target.value;
			isBeginAnotherUploadSession = target.value === "batch";

			try {
				await persistCurrentUpload();
				const payload = immutableCommit(uploadSession, snapshot($state.snapshot(draft), uploadSession.relationships.files));
				const sessionId = uploadSession.id;
				const res = await owner.request<Chapter>(`/upload/${sessionId}/commit`, "POST", payload);
				if (window.location.pathname !== pathname) {
					return;
				}

				if (res?.status === StatusCodes.OK && res.body) {
					uploadSession.is_committed = true;
					uploadSession.can_mutate = false;
					uploadSession.can_retry_commit = false;

					const publication = res.body as Chapter & { publication_scope?: string; publication_status?: string };
					if (publication.publication_status === "accepted_pending_projection") {
						chapter = undefined;
						message = {
							title: "Signed chapter accepted",
							description: "The original protocol accepted this chapter. It is waiting for local catalogue processing before it can be read."
						};
					} else if (publication.publication_scope === "instance-local") {
						chapter = res.body;
						message = {
							title: "Chapter uploaded to this instance",
							description: "The chapter is available on this instance. Original-protocol publication is not configured here."
						};
					} else if (await isPending()) {
						message = {
							title: "Chapter added to approval queue",
							description:
								"As you have not had a chapter approved for this language before, this chapter has been added to the approval queue.<br/><br/> Chapters generally take a day or two to be approved."
						};
					} else {
						chapter = res.body;
						message = {
							title: "Chapter uploaded successfully",
							description:
								"Chapter has been uploaded successfully. It may take a few minutes to process before it becomes visible to the public."
						};
					}
					isShowMessage = true;
				} else if (res?.status === StatusCodes.FORBIDDEN) {
					throw Constants.Error.Forbidden;
				} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
					throw Constants.Error.TooManyRequests;
				} else throw Constants.Error.Unknown;
			} catch (e) {
				await reconcileUploadFailure();
				if (e instanceof Constants.Error.Error) toast.error(e.title, { description: e.body });
				else toast.error(Constants.Error.Unknown.title, { description: Constants.Error.Unknown.body });
			} finally {
				submitter = undefined;
			}
		});
	};

	let lastSavedUpload = $state("");
	let resumeSaveTimer = 0;
	let resumeDisposed = false;
	const showResumeError = (error: unknown) => {
		if (!owner.alive()) return;
		if (error instanceof Constants.Error.Error) toast.error(error.title, { description: error.body });
		else toast.error("Upload could not be restored", { description: "Reload before creating another upload. Existing staging was kept." });
	};
	const restoreUpload = (saved: UploadSession) => {
		owner.assert();
		uploadSession = prepareResume(saved);
		draft = structuredClone(saved.draft ?? {});
		groups = saved.relationships.groups ?? [];
		isOneshot = !draft.volume && !draft.chapter;
		lastSavedUpload = signature(snapshot(draft, saved.relationships.files ?? []));
		if (saved.is_committed) {
			const result = saved.committed_result ?? saved.receipt;
			chapter = result?.relationships?.manga && !["accepted_pending_projection", "pending_projection"].includes(result.publication_status ?? "") ? result : undefined;
			message = { title: chapter ? "Saved chapter restored" : "Signed chapter accepted", description: chapter ? "This chapter has been materialized on this instance." : "The saved publication is waiting for local catalogue processing before it can be read." };
			isBeginAnotherUploadSession = false;
			isShowMessage = true;
		} else toast.info("Upload session restored", { description: resumeNotice(saved) });
	};
	const persistCurrentUpload = async () => {
		if (resumeDisposed || !uploadSession || uploadSession.can_mutate === false || typeof draft.language !== "string" || !draft.language.trim()) return;
		const files = uploadSession.relationships.files ?? [];
		if (files.some(file => file.file || file.error || file.id.length !== 10)) return;
		const value = snapshot($state.snapshot(draft), files);
		if (signature(value) === lastSavedUpload) return;
		const saved = await saveResume(uploadSession, value, owner);
		if (resumeDisposed || uploadSession?.id !== saved.id) return;
		acknowledge(uploadSession, saved);
		lastSavedUpload = signature(value);
	};
	const reconcileUploadFailure = async () => {
		try {
			const saved = await currentUpload(owner);
			if (saved && (saved.manga_id ?? saved.relationships.manga?.id) === manga.id && (!saved.chapter_id || saved.is_committed) && (saved.can_mutate === false || !uploadSession)) restoreUpload(saved);
		} catch { /* Preserve original uncertainty; never replay a mutation. */ }
	};
	$effect(() => {
		if (!resumeReady || !uploadSession || uploadSession.can_mutate === false) return;
		const value = snapshot(draft, uploadSession.relationships.files ?? []);
		if (signature(value) === lastSavedUpload) return;
		window.clearTimeout(resumeSaveTimer);
		resumeSaveTimer = window.setTimeout(() => { void mutex.wait(persistCurrentUpload).catch(showResumeError); }, 500);
		return () => window.clearTimeout(resumeSaveTimer);
	});
	const hasUnsavedUpload = () => !!uploadSession && uploadSession.can_mutate !== false && signature(snapshot(draft, uploadSession.relationships.files ?? [])) !== lastSavedUpload;
	beforeNavigate(navigation => {
		if (!navigation.willUnload && hasUnsavedUpload()) {
			navigation.cancel();
			toast.info("Upload changes are still saving", { description: "Wait for the private staging save before leaving. No session was discarded." });
		}
	});
	onMount(() => {
		const warnUnsaved = (event: BeforeUnloadEvent) => { if (hasUnsavedUpload()) { event.preventDefault(); event.returnValue = ""; } };
		window.addEventListener("beforeunload", warnUnsaved);
		void mutex.wait(async () => {
			const saved = await currentUpload(owner);
			if (resumeDisposed) return;
			if (saved) {
				if ((saved.manga_id ?? saved.relationships.manga?.id) !== manga.id || (saved.chapter_id && !saved.is_committed)) {
					toast.info("Existing upload kept", { description: "Opening its original editor instead of deleting staged work." });
					await goto(saved.chapter_id ? `/chapter/${saved.chapter_id}/edit` : `/title/${saved.manga_id ?? saved.relationships.manga!.id}/upload`);
					return;
				}
				restoreUpload(saved);
			}
			resumeReady = true;
		}).catch(showResumeError);
		return () => { resumeDisposed = true; window.clearTimeout(resumeSaveTimer); window.removeEventListener("beforeunload", warnUnsaved); };
	});

	const cancelCurrentUpload = () => mutex.wait(async () => {
		if (!uploadSession || uploadSession.can_cancel !== true || uploadSession.is_committed) return;
		const staged = uploadSession; owner.assert();
		try {
			const current = await currentUpload(owner); owner.assert();
			if (!current || current.id !== staged.id || current.can_cancel !== true) throw resumeError(409);
			await cancelResume(current, owner); owner.assert();
			if (uploadSession?.id !== staged.id) throw resumeError(409);
			for (const file of staged.relationships.files ?? []) if (file.thumbnail?.startsWith("blob:")) URL.revokeObjectURL(file.thumbnail);
			window.clearTimeout(resumeSaveTimer); uploadSession = undefined; lastSavedUpload = "";
			draft = { language: draft.language }; isOneshot = false; isTemsAccepted = false;
			toast.success("Staged upload cancelled", { description: "The server confirmed cancellation. No chapter publication was cancelled or peer copy removed." });
		} catch (error) { showResumeError(error); }
	});

	const isPending = async () => {
		if (!draft.language) {
			throw Constants.Error.Unknown;
		}

		const res = await owner.request("/upload/check-approval-required", "POST", { language: draft.language });
		if (res?.status === StatusCodes.OK) {
			return true;
		} else if (res?.status === StatusCodes.NO_CONTENT) {
			return false;
		} else if (res?.status === StatusCodes.FORBIDDEN) {
			throw Constants.Error.Forbidden;
		} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
			throw Constants.Error.TooManyRequests;
		} else throw Constants.Error.Unknown;
	};
</script>

<Dialog.Root
	bind:open={isShowMessage}
	onOpenChange={async open => {
		if (open) return;

		isShowMessage = false;
		if (isBeginAnotherUploadSession) {
			isBeginAnotherUploadSession = false;
			uploadSession = undefined;
			draft = { language: draft.language };
			isOneshot = false;

			createUploadSession();
		} else {
			if (chapter) await goto(`/chapter/${chapter.id}/1`);
			else await goto(`/title/${manga.id}${Utils.makeSlug(manga.title)}`);
		}
	}}
>
	<Dialog.Content>
		<Dialog.Header>
			<Dialog.Title>{message?.title}</Dialog.Title>
			<Dialog.Description>
				{@html message?.description}
			</Dialog.Description>
		</Dialog.Header>
		<Dialog.Footer>
			<Dialog.Close>
				{#snippet child({ props })}
					<Button class="border-none" variant="outline" type="button" {...props}>Close</Button>
				{/snippet}
			</Dialog.Close>
		</Dialog.Footer>
	</Dialog.Content>
</Dialog.Root>

<section class="mx-auto flex w-full max-w-270 flex-auto flex-col space-y-5">
	<header class="space-y-5">
		<h2 class="text-xl font-medium">Upload Chapter</h2>
	</header>
	<form class="space-y-5" onsubmit={uploadSession ? commitUploadSession : createUploadSession}>
		<div class="space-y-2">
			<Label>Title</Label>
			<ReportMangaCard {manga} />
		</div>

		<Separator />
		<UploadChapterGroups {user} bind:groups enabled={!uploadSession} disabled={$mutex || !!uploadSession} />

		{#if uploadSession}
			<Separator />
			<UploadChapterMetadata
				bind:draft
				bind:isOneshot
				{isVolumeValid}
				{isChapterValid}
				disabled={($mutex && !!submitter) || !uploadSession}
			/>

			<Separator />
			<UploadChapterPages bind:pages={uploadSession.relationships.files!} disabled={$mutex || !uploadSession} />

			<Separator />
			<div class="space-y-2">
				<div class="flex items-center">
					<Checkbox id="terms" bind:checked={isTemsAccepted} />
					<Label class="block cursor-pointer pl-2" for="terms">
						I have read and agree to the
						<a
							class="hover:text-accent-foreground underline"
							href="/terms"
							target="_blank"
							onclick={e => {
								e.stopPropagation();
								e.stopImmediatePropagation();
							}}
						>
							Terms of Service
						</a>
						and
						<a
							class="hover:text-accent-foreground underline"
							href="/guidelines"
							target="_blank"
							onclick={e => {
								e.stopPropagation();
								e.stopImmediatePropagation();
							}}
						>
							Guidelines
						</a>
					</Label>
				</div>
			</div>
		{/if}

		<Separator />
		<div class="bg-background sticky bottom-0 flex flex-wrap justify-end gap-1 py-1">
			{#if uploadSession}
				{#if uploadSession.can_cancel === true && !uploadSession.is_committed}
					<ConfirmDialog title="Cancel staged upload?" description="Discard this private staging session and its files? Prepared publications cannot be cancelled here." confirmText="Cancel staged upload" onConfirm={dialogMutex => dialogMutex.exec(cancelCurrentUpload)} disabled={$mutex}>
						{#snippet child({ props })}<Button class="border-none" variant="outline" type="button" {...props}>Cancel staged upload</Button>{/snippet}
					</ConfirmDialog>
				{/if}
				<Button class="w-50 border-none" variant="outline" type="submit" value="batch" disabled={$mutex || !isValid}>
					{#if $mutex && submitter === "batch"}
						<Spinner />
					{:else}
						Upload and add another
					{/if}
				</Button>
				<Button class="w-30" type="submit" value="commit" disabled={$mutex || !isValid}>
					{#if $mutex && submitter === "commit"}
						<Spinner />
					{:else}
						Upload
					{/if}
				</Button>
			{:else}
				<Button
					class="w-60 border-none"
					variant="outline"
					type="submit"
					value="nogroup"
					disabled={$mutex || !!groups.length}
				>
					{#if $mutex && submitter === "nogroup"}
						<Spinner />
					{:else}
						Not affiliated with any group
					{/if}
				</Button>
				<Button class="w-30" type="submit" value="group" disabled={$mutex || !groups.length}>
					{#if $mutex && submitter === "group"}
						<Spinner />
					{:else}
						Confirm
					{/if}
				</Button>
			{/if}
		</div>
	</form>
	<div class="space-y-2">
		<strong class="block text-xl font-semibold">Guidelines</strong>
		<Guidelines />
	</div>
</section>
